using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using SonadaBeds.Web.Data;
namespace SonadaBeds.Web.Controllers;
public class ProductsController(SonadaDbContext db,CartService cart):Controller{[Route("products")]public async Task<IActionResult> Index(string? category){var q=db.Products.Include(x=>x.Category).AsQueryable();if(!string.IsNullOrWhiteSpace(category))q=q.Where(x=>x.Category!.Slug==category);return View(await q.OrderBy(x=>x.Name).ToListAsync());}[Route("products/{slug}")]public async Task<IActionResult> Details(string slug){var p=await db.Products.Include(x=>x.Options).Include(x=>x.Reviews).FirstOrDefaultAsync(x=>x.Slug==slug);return p==null?NotFound():View(p);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Add(int id,int quantity=1){await cart.AddAsync(id,Math.Clamp(quantity,1,20),null);return RedirectToAction("Index","Cart");}}
